"""Hidden tests for quirk_indent.py: the contract rows, plus Nemotron's real attempt."""

import pytest

import quirk_indent as qi

EXAMPLE = '```html\n<head>\n  <title>{escaped title}</title>\n  var MODULES = {S(modules)};\n}\n```\n```js\n    not verbatim, wrong tag\n```\n'
EXTRA = '```text\n  <head>\n<head>\n```\n'
BLOB_BLOCK = '```html\n  new Blob([x], { type: "text/js" });\n```\n'
LINES = ['<head>', '  <title>{escaped title}</title>', '  var MODULES = {S(modules)};']
REAL_CONTRACT = '# Contract: single-file.js - packing an exported portfolio site into ONE .html\n\nSplat Studio exports a folder: `viewer/`, `js/`, `vendor/`, `data/portfolio.json`,\n`assets/*.spz`. Kris opens exported pages by double-clicking them, and a browser will\nnot run module scripts or fetch files from `file://`, so the folder never plays. This\nmodule folds the whole site into one page that runs from a double-click. It was\nproven by hand first: the packed page renders the Jackalope with no console errors.\n\nIt runs **inside the studio, in the browser**, so it uses no Node APIs at all: no\n`Buffer`, no `fs`, no `require`. Pure strings and `Uint8Array` in, a string out.\n\n## Public API\n\n```js\nexport const PACKED_GLOBAL = "SPLAT_PACKED";\nexport function rewriteSpecifiers(source, rename) { }   // -> { code, unmapped }\nexport function bytesToBase64(bytes) { }                // Uint8Array -> string\nexport function scriptSafe(value) { }                   // any JSON value -> string\nexport function packedPage(site) { }                    // -> string (the whole .html)\n```\n\nAllowed imports: **none**. You may use the globals `btoa`, `JSON`, `String`,\n`Object`, `Array`, `Math`, `RegExp`. Nothing that touches the page, the network or\nthe disk.\n\n## rewriteSpecifiers(source, rename)\n\n`rename` is a plain object from a relative specifier to a bare module name, e.g.\n`{"./three.core.js": "x:three-core"}`. Find every string literal (single or double\nquotes) that is a module specifier - one that directly follows, with optional\nwhitespace between:\n\n1. `from`\n2. `import` (a side-effect import)\n3. `import(` (a dynamic import)\n\nOnly specifiers that start with `./` or `../` are looked at. For each one:\n\n- if it is a key of `rename`, replace the specifier text with the value, keeping the\n  original quote character. **Only the characters between the quotes change**: the\n  `from` / `import` / `import(` before it and all whitespace stay exactly as they were;\n- otherwise leave it exactly as it is and add it to `unmapped`.\n\nBare specifiers (`"three"`) are never changed and never reported. Return\n`{ code, unmapped }` where `unmapped` lists each unmapped specifier once, in order of\nfirst appearance. Everything outside the replaced specifiers is unchanged.\n\n| source | rename | code | unmapped |\n|---|---|---|---|\n| `import a from "./a.js";` | `{"./a.js": "x:a"}` | `import a from "x:a";` | `[]` |\n| `import \'./b.js\'` | `{"./b.js": "x:b"}` | `import \'x:b\'` | `[]` |\n| `export { c } from "../c.js"` | `{"../c.js": "x:c"}` | `export { c } from "x:c"` | `[]` |\n| `const m = await import( "./d.js" )` | `{"./d.js": "x:d"}` | `const m = await import( "x:d" )` | `[]` |\n| `import t from "three"` | `{}` | unchanged | `[]` |\n| `import e from "./e.js"; import f from "./e.js"` | `{}` | unchanged | `["./e.js"]` |\n| `const s = "./not-an-import.js"` | `{}` | unchanged | `[]` |\n\n## bytesToBase64(bytes)\n\nStandard base64 (RFC 4648, `+` and `/`, `=` padding) of a `Uint8Array`. It must work\nfor arrays of tens of megabytes: build the binary string in chunks of at most 32768\nbytes (`String.fromCharCode.apply(null, chunk)` on a larger array throws "Maximum\ncall stack size exceeded"), then call `btoa` once on the joined string.\n\n| bytes | result |\n|---|---|\n| `[]` | `""` |\n| `[102]` | `"Zg=="` |\n| `[102, 111]` | `"Zm8="` |\n| `[102, 111, 111]` | `"Zm9v"` |\n| `[0, 255, 128]` | `"AP+A"` |\n\n## scriptSafe(value)\n\n`JSON.stringify(value)`, then made safe to paste inside a `<script>` element:\nreplace every `<` with `\\u003c`, every U+2028 with `\\u2028` and every U+2029 with\n`\\u2029` (the six-character escape text). The result is still valid JSON that\nparses back to `value`.\n\n| value | result |\n|---|---|\n| `{"a": 1}` | `{"a":1}` |\n| `"</script>"` | `"\\u003c/script>"` |\n| `"<!--"` | `"\\u003c!--"` |\n\n## packedPage(site)\n\n`site` is:\n\n```js\n{\n  title: "Test yooooo",            // page <title>, HTML-escaped (& < > ")\n  css: "...",                      // viewer.css text\n  body: "...",                     // the viewer\'s <body> inner HTML, WITHOUT scripts\n  modules: { "three": "...", "x:viewer": "..." },   // bare name -> module source\n  entry: "x:viewer",               // the module that starts the page\n  portfolio: "{...}",              // data/portfolio.json as text\n  assets: { "Jackalope.spz": Uint8Array }           // file name -> bytes\n}\n```\n\nReturn exactly this page, where `S(x)` means `scriptSafe(x)` and `B64` is an object\nfrom each asset name to `bytesToBase64` of its bytes:\n\n```html\n<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>{escaped title}</title>\n<style>{css}</style>\n<script>\n(function () {\n  var MODULES = {S(modules)};\n  var ASSETS = {S(B64)};\n  var map = {};\n  for (var name in MODULES) {\n    map[name] = URL.createObjectURL(new Blob([MODULES[name]], { type: "text/javascript" }));\n  }\n  window.SPLAT_PACKED = {\n    portfolio: {S(portfolio)},\n    asset: function (file) {\n      if (!(file in ASSETS)) return null;\n      var s = atob(ASSETS[file]), a = new Uint8Array(s.length);\n      for (var i = 0; i < s.length; i++) a[i] = s.charCodeAt(i);\n      return { fileBytes: a, fileName: file };\n    }\n  };\n  var im = document.createElement("script");\n  im.type = "importmap";\n  im.textContent = JSON.stringify({ imports: map });\n  document.head.appendChild(im);\n  var go = document.createElement("script");\n  go.type = "module";\n  go.textContent = "import " + JSON.stringify({S(entry)}) + ";";\n  document.head.appendChild(go);\n})();\n</script>\n</head>\n<body>{body}</body>\n</html>\n```\n\n**The `{...}` markers above are placeholders, not text.** The page never contains\n`{S(modules)}` or `{escaped title}`; it contains the values. Here is the complete,\nexact output for this small site - the hidden tests compare byte for byte:\n\n```js\npackedPage({\n  title: "A & B", css: "b{c:d}", body: "<p>hi</p>",\n  modules: { "x:main": \'import "x:lib";\', "x:lib": "export const n = 1;" },\n  entry: "x:main", portfolio: \'{"title":"A & B"}\',\n  assets: { "m.spz": new Uint8Array([1, 2, 3]) },\n})\n```\n\nreturns\n\n```html\n<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>A &amp; B</title>\n<style>b{c:d}</style>\n<script>\n(function () {\n  var MODULES = {"x:main":"import \\"x:lib\\";","x:lib":"export const n = 1;"};\n  var ASSETS = {"m.spz":"AQID"};\n  var map = {};\n  for (var name in MODULES) {\n    map[name] = URL.createObjectURL(new Blob([MODULES[name]], { type: "text/javascript" }));\n  }\n  window.SPLAT_PACKED = {\n    portfolio: "{\\"title\\":\\"A & B\\"}",\n    asset: function (file) {\n      if (!(file in ASSETS)) return null;\n      var s = atob(ASSETS[file]), a = new Uint8Array(s.length);\n      for (var i = 0; i < s.length; i++) a[i] = s.charCodeAt(i);\n      return { fileBytes: a, fileName: file };\n    }\n  };\n  var im = document.createElement("script");\n  im.type = "importmap";\n  im.textContent = JSON.stringify({ imports: map });\n  document.head.appendChild(im);\n  var go = document.createElement("script");\n  go.type = "module";\n  go.textContent = "import " + JSON.stringify("x:main") + ";";\n  document.head.appendChild(go);\n})();\n</script>\n</head>\n<body><p>hi</p></body>\n</html>\n```\n\nLines end with `\\n`, including the last. Indentation is two spaces per level, exactly\nas shown. The `{...}` placeholders are replaced with no extra spaces. `css` and\n`body` are inserted as they are - they come from the studio\'s own files.\n\nRules, in order:\n\n1. `site.entry` must be a key of `site.modules`, otherwise throw an `Error` whose\n   message contains the entry name.\n2. Every value in `site.assets` must be a `Uint8Array`, otherwise throw an `Error`\n   whose message contains that asset\'s name.\n3. Build and return the page.\n\nThe tests run the `<script>` block with fake `document`, `URL`, `Blob` and `window`\nobjects and check that `SPLAT_PACKED.asset(name)` returns the original bytes, that\n`SPLAT_PACKED.portfolio` is the original text, and that the import map names every\nmodule.\n'
REAL_SOURCE = 'export const PACKED_GLOBAL = "SPLAT_PACKED";\n\nexport function rewriteSpecifiers(source, rename) {\n  const regex = /(from|import\\s*\\(|import)(\\s*)([\\"\'])([^\\"\']*?)\\3/g;\n  const unmapped = [];\n  const seen = new Set();\n  const parts = [];\n  let lastIndex = 0;\n  let match;\n  while ((match = regex.exec(source)) !== null) {\n    parts.push(source.slice(lastIndex, match.index));\n    const keyword = match[1];\n    const whitespace = match[2];\n    const quote = match[3];\n    const content = match[4];\n    if (/^\\.\\/|^\\.\\.\\//.test(content)) {\n      if (Object.prototype.hasOwnProperty.call(rename, content)) {\n        parts.push(keyword + whitespace + quote + rename[content] + quote);\n      } else {\n        parts.push(match[0]);\n        if (!seen.has(content)) {\n          seen.add(content);\n          unmapped.push(content);\n        }\n      }\n    } else {\n      parts.push(match[0]);\n    }\n    lastIndex = regex.lastIndex;\n  }\n  parts.push(source.slice(lastIndex));\n  return { code: parts.join(\'\'), unmapped };\n}\n\nexport function bytesToBase64(bytes) {\n  if (bytes.length === 0) return "";\n  const chunkSize = 32768;\n  const chunks = [];\n  for (let i = 0; i < bytes.length; i += chunkSize) {\n    const chunk = bytes.subarray(i, i + chunkSize);\n    chunks.push(String.fromCharCode.apply(null, chunk));\n  }\n  return btoa(chunks.join(\'\'));\n}\n\nexport function scriptSafe(value) {\n  let json = JSON.stringify(value);\n  return json.replace(/</g, \'\\\\u003c\')\n             .replace(/\\u2028/g, \'\\\\u2028\')\n             .replace(/\\u2029/g, \'\\\\u2029\');\n}\n\nexport function packedPage(site) {\n  if (!site.modules.hasOwnProperty(site.entry)) {\n    throw new Error("Entry module not found: " + site.entry);\n  }\n  for (const fileName in site.assets) {\n    if (!(site.assets[fileName] instanceof Uint8Array)) {\n      throw new Error("Asset is not a Uint8Array: " + fileName);\n    }\n  }\n  const modulesObj = {};\n  for (const key in site.modules) {\n    modulesObj[key] = scriptSafe(site.modules[key]);\n  }\n  const assetsObj = {};\n  for (const fileName in site.assets) {\n    assetsObj[fileName] = bytesToBase64(site.assets[fileName]);\n  }\n  const escapedTitle = site.title\n    .replace(/&/g, \'&amp;\')\n    .replace(/</g, \'&lt;\')\n    .replace(/>/g, \'&gt;\')\n    .replace(/"/g, \'&quot;\');\n  const lines = [\n    \'<!doctype html>\',\n    \'<html lang="en">\',\n    \'  <head>\',\n    \'    <meta charset="utf-8">\',\n    \'    <meta name="viewport" content="width=device-width, initial-scale=1">\',\n    \'    <title>\' + escapedTitle + \'</title>\',\n    \'    <style>\' + site.css + \'</style>\',\n    \'    <script>\',\n    \'      (function () {\',\n    \'        var MODULES = \' + JSON.stringify(modulesObj) + \';\',\n    \'        var ASSETS = \' + JSON.stringify(assetsObj) + \';\',\n    \'        var map = {};\',\n    \'        for (var name in MODULES) {\',\n    \'          map[name] = URL.createObjectURL(new Blob([MODULES[name]], { type: "text/javascript" }));\',\n    \'        }\',\n    \'        window.SPLAT_PACKED = {\',\n    \'          portfolio: \' + JSON.stringify(scriptSafe(site.portfolio)) + \',\',\n    \'          asset: function (file) {\',\n    \'            if (!(file in ASSETS)) return null;\',\n    \'            var s = atob(ASSETS[file]), a = new Uint8Array(s.length);\',\n    \'            for (var i = 0; i < s.length; i++) a[i] = s.charCodeAt(i);\',\n    \'            return { fileBytes: a, fileName: file };\',\n    \'          }\',\n    \'        };\',\n    \'        var im = document.createElement("script");\',\n    \'        im.type = "importmap";\',\n    \'        im.textContent = JSON.stringify({ imports: map });\',\n    \'        document.head.appendChild(im);\',\n    \'        var go = document.createElement("script");\',\n    \'        go.type = "module";\',\n    \'        go.textContent = "import " + JSON.stringify(scriptSafe(site.entry)) + ";";\',\n    \'        document.head.appendChild(go);\',\n    \'      })();\',\n    \'    </script>\',\n    \'  </head>\',\n    \'  <body>\' + site.body + \'</body>\',\n    \'</html>\'\n  ];\n  return lines.join(\'\\n\') + \'\\n\';\n}\n'


def test_constants():
    assert qi.VERBATIM_TAGS == ("html", "text", "verbatim")
    assert qi.MIN_CHARS == 6


def test_verbatim_lines_example():
    assert qi.verbatim_lines(EXAMPLE) == LINES


def test_verbatim_lines_keep_order_and_first_copy_across_blocks():
    got = qi.verbatim_lines(EXAMPLE + EXTRA)
    assert got == LINES + ["  <head>"]


@pytest.mark.parametrize("source,expected", [("'<head>',", []), ("'  <head>',", [{'line': 1, 'text': '<head>', 'expected': 0, 'found': 2}]), ('"    <title>" + t + "</title>"', [{'line': 1, 'text': '<title>', 'expected': 2, 'found': 4}]), ("'        var MODULES = ' + x + ';\\n'", [{'line': 1, 'text': 'var MODULES =', 'expected': 2, 'found': 8}]), ('"  <head>\\n"', [{'line': 1, 'text': '<head>', 'expected': 0, 'found': 2}]), ('const s = "  hello there";', [])])
def test_indent_drift_table(source, expected):
    assert qi.indent_drift(source, LINES) == expected


def test_line_numbers_count_from_one():
    found = qi.indent_drift("x = 1;" + chr(10) + "y = '  <head>';", LINES)
    assert [f["line"] for f in found] == [2]


@pytest.mark.parametrize("source,expected", [('a = [\'  <head>\', "    <title>"];', ('a = [\'<head>\', "  <title>"];', 2)), ('x = "  <head>\\n";', ('x = "<head>\\n";', 1)), ("y = '<head>';", ("y = '<head>';", 0))])
def test_fix_table(source, expected):
    assert qi.fix_indent_drift(source, LINES) == expected


def test_fix_is_idempotent():
    once, _ = qi.fix_indent_drift("a = ['  <head>', '    <title>'];", LINES)
    assert qi.fix_indent_drift(once, LINES) == (once, 0)


def test_a_brace_followed_by_a_space_is_not_a_placeholder():
    lines = qi.verbatim_lines(BLOB_BLOCK)
    assert qi.indent_drift("s = '    new Blob([x], { type: " + chr(34) + "text/js"
                           + chr(34) + " });';", lines) == [
        {"line": 1, "text": "new Blob([x], { type: " + chr(34) + "text/js" + chr(34)
         + " });", "expected": 2, "found": 4}]


def test_nemotrons_real_attempt():
    lines = qi.verbatim_lines(REAL_CONTRACT)
    assert len(lines) == 40
    assert len(qi.indent_drift(REAL_SOURCE, lines)) == 29
    fixed, count = qi.fix_indent_drift(REAL_SOURCE, lines)
    assert count == 29
    assert qi.indent_drift(fixed, lines) == []
    assert fixed.count(chr(10)) == REAL_SOURCE.count(chr(10))
